class Solution:
    def buildWall(self, height: int, width: int, bricks: List[int]) -> int:
        MOD = 10 ** 9 + 7
        opts = sorted({b for b in bricks if b <= width})
        masks = []

        def dfs(pos, mask):
            if pos == width:
                masks.append(mask)
                return
            for b in opts:
                if pos + b > width:
                    break
                dfs(pos + b, mask | (1 << pos + b - 1) if pos + b < width else mask)

        dfs(0, 0)
        dp = {m: 1 for m in masks}
        for _ in range(height - 1):
            ndp = {m: 0 for m in masks}
            for m in masks:
                for pm, c in dp.items():
                    if not (m & pm):
                        ndp[m] = (ndp[m] + c) % MOD
            dp = ndp
        return sum(dp.values()) % MOD

