class Solution {
public:
    int buildWall(int height, int width, vector<int>& bricks) {
        const long long MOD = 1e9 + 7;
        vector<int> bs(bricks);
        sort(bs.begin(), bs.end());
        bs.erase(unique(bs.begin(), bs.end()), bs.end());
        vector<long long> masks;
        function<void(int, long long)> dfs = [&](int pos, long long mask) {
            if (pos == width) {
                masks.push_back(mask);
                return;
            }
            for (int b : bs) {
                if (pos + b > width) break;
                dfs(pos + b, pos + b < width ? mask | (1LL << (pos + b - 1)) : mask);
            }
        };
        dfs(0, 0);
        int p = masks.size();
        vector<long long> dp(p, 1), ndp(p);
        for (int row = 1; row < height; row++) {
            fill(ndp.begin(), ndp.end(), 0);
            for (int m = 0; m < p; m++)
                for (int pm = 0; pm < p; pm++)
                    if (!(masks[m] & masks[pm]))
                        ndp[m] = (ndp[m] + dp[pm]) % MOD;
            swap(dp, ndp);
        }
        long long ans = 0;
        for (long long c : dp) ans = (ans + c) % MOD;
        return (int)ans;
    }
};

