class Solution {
    private List<Long> masks = new ArrayList<>();

    public int buildWall(int height, int width, int[] bricks) {
        final long MOD = 1_000_000_007L;
        TreeSet<Integer> opts = new TreeSet<>();
        for (int b : bricks) if (b <= width) opts.add(b);
        dfs(0, 0, width, opts);
        int p = masks.size();
        long[] dp = new long[p], ndp = new long[p];
        Arrays.fill(dp, 1);
        for (int row = 1; row < height; row++) {
            Arrays.fill(ndp, 0);
            for (int m = 0; m < p; m++)
                for (int pm = 0; pm < p; pm++)
                    if ((masks.get(m) & masks.get(pm)) == 0)
                        ndp[m] = (ndp[m] + dp[pm]) % MOD;
            System.arraycopy(ndp, 0, dp, 0, p);
        }
        long ans = 0;
        for (long c : dp) ans = (ans + c) % MOD;
        return (int) ans;
    }

    private void dfs(int pos, long mask, int width, TreeSet<Integer> opts) {
        if (pos == width) {
            masks.add(mask);
            return;
        }
        for (int b : opts) {
            if (pos + b > width) break;
            dfs(pos + b, pos + b < width ? mask | (1L << (pos + b - 1)) : mask, width, opts);
        }
    }
}

