from functools import cache


class Solution:
    def buildWall(self, height: int, width: int, bricks: List[int]) -> int:
        MOD = 10 ** 9 + 7
        opts = sorted({b for b in bricks if b <= width})
        masks = []

        def gen(pos, mask):
            if pos == width:
                masks.append(mask)
                return
            for b in opts:
                if pos + b > width:
                    break
                gen(pos + b, mask | (1 << pos + b - 1) if pos + b < width else mask)

        gen(0, 0)

        @cache
        def go(left, last):
            if left == 0:
                return 1
            total = 0
            for m in masks:
                if not (m & last):
                    total += go(left - 1, m)
            return total % MOD

        return go(height, 0)

