public:
    int buildWall(int height, int width, vector<int>& bricks) {
        const long long MOD = 1e9 + 7;
        vector<int> bs(bricks);
        sort(bs.begin(), bs.end());
        bs.erase(unique(bs.begin(), bs.end()), bs.end());
        vector<long long> masks;
        function<void(int, long long)> gen = [&](int pos, long long mask) {
            if (pos == width) {
                masks.push_back(mask);
                return;
            }
            for (int b : bs) {
                if (pos + b > width) break;
                gen(pos + b, pos + b < width ? mask | (1LL << (pos + b - 1)) : mask);
            }
        };
        gen(0, 0);
        int p = masks.size();
        vector<vector<long long>> memo(height, vector<long long>(max(p, 1), -1));
        function<long long(int, int)> go = [&](int left, int idx) -> long long {
            if (left == 0) return 1;
            long long& res = memo[left][idx];
            if (res != -1) return res;
            res = 0;
            for (int j = 0; j < p; j++) {
                if (masks[idx] & masks[j]) continue;
                res = (res + go(left - 1, j)) % MOD;
            }
            return res;
        };
        long long ans = 0;
        for (int m = 0; m < p; m++) ans = (ans + go(height - 1, m)) % MOD;
        return (int)(ans % MOD);
    }
};

