class Solution {
    private long[] masks;
    private long[][] memo;

    public int buildWall(int height, int width, int[] bricks) {
        final long MOD = 1_000_000_007L;
        TreeSet<Integer> opts = new TreeSet<>();
        for (int b : bricks) if (b <= width) opts.add(b);
        List<Long> list = new ArrayList<>();
        gen(0, 0, width, opts, list);
        int p = list.size();
        masks = new long[p];
        for (int i = 0; i < p; i++) masks[i] = list.get(i);
        memo = new long[Math.max(height, 1)][Math.max(p, 1)];
        for (long[] row : memo) Arrays.fill(row, -1);
        long ans = 0;
        for (int m = 0; m < p; m++) ans = (ans + go(height - 1, m)) % MOD;
        return (int) ans;
    }

    private long go(int left, int idx) {
        if (left == 0) return 1;
        if (memo[left][idx] != -1) return memo[left][idx];
        long res = 0;
        for (int j = 0; j < masks.length; j++) {
            if ((masks[idx] & masks[j]) != 0) continue;
            res = (res + go(left - 1, j)) % 1_000_000_007L;
        }
        return memo[left][idx] = res;
    }

    private void gen(int pos, long mask, int width, TreeSet<Integer> opts, List<Long> out) {
        if (pos == width) {
            out.add(mask);
            return;
        }
        for (int b : opts) {
            if (pos + b > width) break;
            gen(pos + b, pos + b < width ? mask | (1L << (pos + b - 1)) : mask, width, opts, out);
        }
    }
}

