    const MOD = 1e9 + 7;
    const opts = [...new Set(bricks.filter(b => b <= width))].sort((a, b) => a - b);
    const masks = [];
    const gen = (pos, mask) => {
        if (pos === width) {
            masks.push(mask);
            return;
        }
        for (const b of opts) {
            if (pos + b > width) break;
            gen(pos + b, pos + b < width ? mask | (1 << (pos + b - 1)) : mask);
        }
    };
    gen(0, 0);
    const memo = new Map();
    const go = (left, last) => {
        if (left === 0) return 1;
        const key = left * 4096 + last;
        if (memo.has(key)) return memo.get(key);
        let total = 0;
        for (const m of masks) if (!(m & last)) total = (total + go(left - 1, m)) % MOD;
        memo.set(key, total);
        return total;
    };
    return go(height, 0);
};
